export type ApiPath = keyof paths;
export type ApiOperationId = keyof operations;

export type JsonRequestBody<OperationId extends ApiOperationId> =
  NonNullable<operations[OperationId]["requestBody"]> extends { content: { "application/json": infer Body } }
    ? Body
    : unknown;

export type SuccessResponseStatus<OperationId extends ApiOperationId> =
  Extract<keyof operations[OperationId]["responses"], `2${number}${number}`>;

export type JsonSuccessResponseBody<
  OperationId extends ApiOperationId,
  Status extends SuccessResponseStatus<OperationId>,
> = operations[OperationId]["responses"][Status] extends { content: { "application/json": infer Body } }
  ? Body
  : unknown;
